// THE FORM BYTE IS READ FIRST, before the trailer and before any body, so a
// file that is both a newer form and damaged is a REFUSAL and never damage.
// A refusal moves none of the report's five counters, because nothing was
// decoded and there is nothing to count (docs/SPEC-TABLES.md §3).
inline TableOpenVerdict TableEntityLoadVerdict( TableEntity & value, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    TableReport ignored;
    TableReport * to = report != NULL ? report : &ignored;
    TableIdTable table;
    int64_t body_bytes = 0;
    const TableOpenVerdict verdict = TableOpen( buffer, bytes, table, body_bytes );
    if ( verdict != TableOpenOk )
    {
        TableEntityReset( value );
        if ( verdict == TableOpenDamaged ) { to->malformed = true; }
        else
        {
            // FORM 2 IS A STREAM FORM AND NEVER A FILE FORM: a message
            // stored on its own is not readable, because its table is
            // somewhere else, and the refusal says so BY NAME rather than
            // merely by form byte (docs/SPEC-TABLES.md §3.3).
            to->refused = true;
            to->reason = bytes > 0 && buffer[0] == kTableWireMessageForm ? message_form_as_file : newer_form;
        }
        return verdict;
    }
    // ANY BYTE BETWEEN THE ROOT'S TERMINATOR AND THE TABLE'S FIRST ENTRY IS
    // MALFORMED, because no field claims it and the two ends of the file
    // have met: nothing is decoded and one event is counted (§3).
    if ( TableBodyEndsEarly( buffer + 1, body_bytes, table ) )
    {
        TableEntityReset( value );
        to->malformed = true;
        return TableOpenDamaged;
    }
    TableReader r( buffer + 1, body_bytes, to, &table );
    r.nested = false; // the ROOT body, the one that may carry a node table
    if ( !TableEntityLoadBody( r, value ) ) { return TableOpenBodyStopped; }
    return TableOpenOk;
}

// The bool is the BODY reaching its own terminator, and it is what it has
// always been: framing damage inside a field keeps what it decoded, flags
// the report and reads on, so this answers true (docs/SPEC-TABLES.md §4).
// False is a wire nothing could be decoded from: a refusal, a table that
// cannot be read whole, or a root body the walk could not finish.
inline bool TableEntityLoad( TableEntity & value, const uint8_t * buffer, int64_t bytes, TableReport * report )
{
    return TableEntityLoadVerdict( value, buffer, bytes, report ) == TableOpenOk;
}

// The BITPACKED body's cost, in BITS (docs/SPEC-TABLES.md §3.3). `at` is the
// body's own bit position in the batch, because a `string(N)` ALIGNS before
// its bytes and an align costs what the position says it costs.
inline int64_t TableEntityMeasureMessageBody( int64_t at, const TableEntity & value )
{
    int64_t bits = 0;
    if ( value.entity_id != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 12;
    }
    if ( value.pos_x != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 15;
    }
    if ( value.pos_y != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 15;
    }
    if ( value.pos_z != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 15;
    }
    if ( value.yaw != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 9;
    }
    if ( value.pitch != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 9;
    }
    if ( value.vel_x != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 12;
    }
    if ( value.vel_y != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 12;
    }
    if ( value.vel_z != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 12;
    }
    if ( value.health != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 10;
    }
    if ( value.weapon != TableWeapon::None )
    {
        if ( !TableEnumNamed( value.weapon ) ) { return -1; }
        bits += kTableMessageRefBitsHere;
        bits += kTableMessageRefBitsHere;
    }
    if ( value.damage != 0 )
    {
        bits += kTableMessageRefBitsHere;
        bits += 8;
    }
    if ( value.moving != false )
    {
        bits += kTableMessageRefBitsHere;
        bits += 1;
    }
    if ( value.firing != false )
    {
        bits += kTableMessageRefBitsHere;
        bits += 1;
    }
    bits += kTableMessageRefBitsHere; // the ZERO REFERENCE that ends the body
    (void) at;
    return bits;
}

// The BITPACKED body: the fields, then the ZERO REFERENCE that ends it. No
// kind byte rides at all, and no length frames a nested body, because a
// body is self-delimiting: it is written where the file form put an L.
inline bool TableEntitySaveMessageBody( TableBitWriter & w, const TableEntity & value )
{
    if ( value.entity_id != 0 )
    {
        w.put( 3, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.entity_id ), 12 );
    }
    if ( value.pos_x != 0 )
    {
        w.put( 4, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.pos_x ) - 18446744073709535233ull, 15 );
    }
    if ( value.pos_y != 0 )
    {
        w.put( 5, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.pos_y ) - 18446744073709535233ull, 15 );
    }
    if ( value.pos_z != 0 )
    {
        w.put( 6, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.pos_z ) - 18446744073709535233ull, 15 );
    }
    if ( value.yaw != 0 )
    {
        w.put( 7, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.yaw ), 9 );
    }
    if ( value.pitch != 0 )
    {
        w.put( 8, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.pitch ), 9 );
    }
    if ( value.vel_x != 0 )
    {
        w.put( 9, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.vel_x ) - 18446744073709549568ull, 12 );
    }
    if ( value.vel_y != 0 )
    {
        w.put( 10, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.vel_y ) - 18446744073709549568ull, 12 );
    }
    if ( value.vel_z != 0 )
    {
        w.put( 11, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.vel_z ) - 18446744073709549568ull, 12 );
    }
    if ( value.health != 0 )
    {
        w.put( 12, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.health ), 10 );
    }
    if ( value.weapon != TableWeapon::None )
    {
        if ( !TableEnumNamed( value.weapon ) ) { return false; }
        w.put( 13, kTableMessageRefBitsHere );
        {
            uint64_t slot = 0;
            if ( !TableEnumSlot( value.weapon, slot ) ) { return false; }
            w.put( slot, kTableMessageRefBitsHere );
        }
    }
    if ( value.damage != 0 )
    {
        w.put( 14, kTableMessageRefBitsHere );
        w.put( (uint64_t) ( value.damage ), 8 );
    }
    if ( value.moving != false )
    {
        w.put( 15, kTableMessageRefBitsHere );
        w.put( value.moving ? 1 : 0, 1 );
    }
    if ( value.firing != false )
    {
        w.put( 16, kTableMessageRefBitsHere );
        w.put( value.firing ? 1 : 0, 1 );
    }
    w.put( 0, kTableMessageRefBitsHere ); // the ZERO REFERENCE that ends the body
    return !w.overflow;
}

